import { useLocation } from 'react-router-dom';
import { useState, useEffect } from 'react';

const titles = {
  '/analytics': ['📊 Analytics Dashboard', 'aria / analytics'],
  '/chat':      ['💬 Chat Interface',       'aria / chat'],
  '/upload':    ['📁 Document Upload',      'aria / upload'],
  '/settings':  ['⚙️ Settings',             'aria / settings'],
};

export default function Topbar({ API, onLogout }) {
  const { pathname } = useLocation();
  const [online, setOnline] = useState(false);
  const [title, crumb] = titles[pathname] || ['ARIA', 'aria'];

  useEffect(() => {
    fetch(`${API}/health`)
      .then(r => r.json())
      .then(d => setOnline(d.rag_index_loaded))
      .catch(() => setOnline(false));
  }, [API]);

  return (
    <div style={{
      height: 52, borderBottom: '1px solid var(--border)',
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      padding: '0 24px', background: 'var(--bg2)', flexShrink: 0
    }}>
      <div>
        <div style={{ fontSize: '0.9rem', fontWeight: 600 }}>{title}</div>
        <div style={{ fontSize: '0.65rem', color: 'var(--text3)', fontFamily: 'var(--mono)' }}>{crumb}</div>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: 6,
          padding: '4px 10px', borderRadius: 20,
          background: online ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)',
          border: `1px solid ${online ? 'rgba(16,185,129,0.25)' : 'rgba(239,68,68,0.25)'}`,
          fontSize: '0.62rem', color: online ? 'var(--green)' : 'var(--red)',
          fontFamily: 'var(--mono)'
        }}>
          <div style={{
            width: 6, height: 6, borderRadius: '50%',
            background: online ? 'var(--green)' : 'var(--red)',
            animation: 'pulse 2s infinite'
          }} />
          {online ? 'RAG Online' : 'Backend Offline'}
        </div>
        <button onClick={onLogout} style={{
          padding: '5px 12px', borderRadius: 7,
          border: '1px solid var(--border)', background: 'var(--surface)',
          color: 'var(--text2)', fontSize: '0.7rem', cursor: 'pointer',
          fontFamily: 'var(--sans)'
        }}>🚪 Logout</button>
      </div>
    </div>
  );
}
